// The clock's protocol decoder against messages from the gateway's Python encoder
// (wire_fixtures.h, generated by tools/make_wire_fixtures.py), and against forged,
// replayed and inconsistent messages. Runs under AddressSanitizer and UBSan.

#include <unity.h>

#include <cstring>
#include <vector>

#include "wire.h"
#include "../wire_fixtures.h"

using namespace core;

namespace {

std::vector<uint8_t> bytes(const uint8_t* data, size_t length) { return std::vector<uint8_t>(data, data + length); }

// Re-signs a message after editing its body, as a gateway with a bug (but the right key) would.
void resign(std::vector<uint8_t>& message, const GatewayKey& key) {
  const size_t body = message.size() - kSha256Bytes;
  uint8_t mac[kSha256Bytes];
  hmac_sha256(key, message.data(), body, mac);
  std::memcpy(message.data() + body, mac, sizeof(mac));
}

}  // namespace

static GatewayKey g_key;

void setUp() {
  for (size_t i = 0; i < sizeof(g_key); ++i) {
    g_key[i] = static_cast<uint8_t>(i);
  }
}
void tearDown() {}

// Every field the gateway encodes must reach the screen with the same meaning.
void test_snapshot_from_the_gateway_decodes_field_for_field() {
  Snapshot s;
  TEST_ASSERT_EQUAL_STRING("ok", wire_result_name(decode_snapshot(fixtures::kSnapshot, sizeof(fixtures::kSnapshot),
                                                                  g_key, fixtures::kNonce, s)));

  TEST_ASSERT_EQUAL_STRING("yellow", alert_level_name(s.alert_level));
  TEST_ASSERT_FALSE(s.alerts_stale);
  TEST_ASSERT_TRUE(s.threats_stale);
  TEST_ASSERT_EQUAL(12, s.alerts_age_s);
  TEST_ASSERT_EQUAL(190, s.threats_age_s);
  TEST_ASSERT_EQUAL_UINT32(93784, s.alert_duration_s);
  TEST_ASSERT_EQUAL_HEX32(fixtures::kBasemapVersion, s.basemap_version);
  TEST_ASSERT_FLOAT_WITHIN(0.001f, 4.0f, s.px_per_km);
  TEST_ASSERT_EQUAL(2, static_cast<int>(s.ring_km.size()));
  TEST_ASSERT_EQUAL(10, s.ring_km[0]);
  TEST_ASSERT_EQUAL(20, s.ring_km[1]);
  TEST_ASSERT_EQUAL(3, s.threats_in_watch);
  TEST_ASSERT_EQUAL(1, s.area_only_in_region);
  TEST_ASSERT_FLOAT_WITHIN(0.01f, 7.4f, s.nearest_km);
  TEST_ASSERT_EQUAL_STRING("missile", threat_kind_name(s.nearest_kind));
  TEST_ASSERT_EQUAL(225, s.nearest_heading_deg);
  TEST_ASSERT_FALSE(s.nearest_advisory);
  TEST_ASSERT_TRUE(s.nearest_stale);

  TEST_ASSERT_EQUAL(2, static_cast<int>(s.markers.size()));
  const Marker& missile = s.markers[0];
  TEST_ASSERT_EQUAL(130, missile.point.x);
  TEST_ASSERT_EQUAL(95, missile.point.y);
  TEST_ASSERT_EQUAL(225, missile.heading_deg);
  TEST_ASSERT_TRUE(missile.stale);
  TEST_ASSERT_FALSE(missile.advisory);
  TEST_ASSERT_EQUAL(3, missile.trail_count);  // oldest first
  TEST_ASSERT_EQUAL(160, missile.trail[0].x);
  TEST_ASSERT_EQUAL(60, missile.trail[0].y);
  TEST_ASSERT_EQUAL(140, missile.trail[2].x);
  TEST_ASSERT_EQUAL(84, missile.trail[2].y);
  const Marker& drone = s.markers[1];
  TEST_ASSERT_EQUAL(-5, drone.point.x);  // off-screen positions keep their sign
  TEST_ASSERT_EQUAL(250, drone.point.y);
  TEST_ASSERT_EQUAL(-1, drone.heading_deg);
  TEST_ASSERT_EQUAL_STRING("uav", threat_kind_name(drone.kind));
  TEST_ASSERT_TRUE(drone.approximate);
  TEST_ASSERT_TRUE(drone.advisory);
  TEST_ASSERT_EQUAL(40, drone.uncertainty_px);
  TEST_ASSERT_EQUAL(0, drone.trail_count);
}

// Anyone on the LAN can answer the clock's requests. A forged, altered or replayed reply
// must be refused and leave the last good picture in place.
void test_altered_or_replayed_snapshots_never_change_the_picture() {
  Snapshot s;
  s.threats_in_watch = 777;  // marks the picture as untouched
  std::vector<uint8_t> message = bytes(fixtures::kSnapshot, sizeof(fixtures::kSnapshot));
  for (size_t i = 0; i < message.size(); ++i) {
    message[i] ^= 0x01;
    TEST_ASSERT_NOT_EQUAL_MESSAGE(static_cast<int>(WireResult::Ok),
                                  static_cast<int>(decode_snapshot(message.data(), message.size(), g_key,
                                                                   fixtures::kNonce, s)),
                                  "a message with one changed bit was accepted");
    message[i] ^= 0x01;
  }
  TEST_ASSERT_EQUAL_STRING("wrong_nonce", wire_result_name(decode_snapshot(message.data(), message.size(), g_key,
                                                                           fixtures::kNonce + 1, s)));
  GatewayKey other;
  std::memcpy(other, g_key, sizeof(other));
  other[31] ^= 0x80;
  TEST_ASSERT_EQUAL_STRING("bad_mac", wire_result_name(decode_snapshot(message.data(), message.size(), other,
                                                                       fixtures::kNonce, s)));
  TEST_ASSERT_EQUAL(777, s.threats_in_watch);
}

// The counts drive every read. A message whose counts disagree with its length must be
// refused even when correctly signed: too high would read past the reply buffer, too low
// would drop markers silently.
void test_signed_snapshot_with_counts_that_disagree_with_its_length_is_malformed() {
  std::vector<uint8_t> message = bytes(fixtures::kSnapshot, sizeof(fixtures::kSnapshot));
  constexpr size_t kMarkerCount = 6 + 31 - 1;
  constexpr size_t kFirstTrailCount = 6 + 31 + 9;
  Snapshot s;
  for (const auto& [offset, value] : {std::pair<size_t, uint8_t>{kMarkerCount, 1},
                                      std::pair<size_t, uint8_t>{kMarkerCount, 3},
                                      std::pair<size_t, uint8_t>{kMarkerCount, 200},
                                      std::pair<size_t, uint8_t>{kFirstTrailCount, 6},
                                      std::pair<size_t, uint8_t>{kFirstTrailCount, 7}}) {
    std::vector<uint8_t> edited = message;
    edited[offset] = value;
    resign(edited, g_key);
    TEST_ASSERT_EQUAL_STRING("malformed",
                             wire_result_name(decode_snapshot(edited.data(), edited.size(), g_key, fixtures::kNonce, s)));
  }
}

void test_basemap_from_the_gateway_draws_its_runs() {
  Basemap map;
  TEST_ASSERT_EQUAL_STRING("ok", wire_result_name(map.load(fixtures::kBasemap, sizeof(fixtures::kBasemap), g_key,
                                                           fixtures::kNonce)));
  TEST_ASSERT_EQUAL_HEX32(fixtures::kBasemapVersion, map.version());

  struct Run {
    int x, length;
    uint16_t color;
  };
  std::vector<Run> runs;
  map.for_each_run(120, [&](int16_t x, int16_t length, uint16_t color) { runs.push_back({x, length, color}); });
  TEST_ASSERT_EQUAL(3, static_cast<int>(runs.size()));
  TEST_ASSERT_EQUAL(0, runs[0].x);
  TEST_ASSERT_EQUAL(100, runs[0].length);
  TEST_ASSERT_EQUAL_HEX16(0x18C6, runs[0].color);  // palette[0]
  TEST_ASSERT_EQUAL(100, runs[1].x);
  TEST_ASSERT_EQUAL(40, runs[1].length);
  TEST_ASSERT_EQUAL_HEX16(0x18C7, runs[1].color);  // palette[1]
  TEST_ASSERT_EQUAL(140, runs[2].x);
  TEST_ASSERT_EQUAL(100, runs[2].length);
  TEST_ASSERT_EQUAL_HEX16(0x18CB, runs[2].color);  // palette[5]

  // Runs of up to 15 pixels take one byte each; this row mixes them with a long one.
  runs.clear();
  map.for_each_run(121, [&](int16_t x, int16_t length, uint16_t color) { runs.push_back({x, length, color}); });
  TEST_ASSERT_EQUAL(4, static_cast<int>(runs.size()));
  TEST_ASSERT_EQUAL(7, runs[0].length);
  TEST_ASSERT_EQUAL_HEX16(0x18C8, runs[0].color);  // palette[2]
  TEST_ASSERT_EQUAL(7, runs[1].x);
  TEST_ASSERT_EQUAL(1, runs[1].length);
  TEST_ASSERT_EQUAL_HEX16(0x18D5, runs[1].color);  // palette[15]
  TEST_ASSERT_EQUAL(8, runs[2].x);
  TEST_ASSERT_EQUAL(15, runs[2].length);
  TEST_ASSERT_EQUAL_HEX16(0x18C9, runs[2].color);  // palette[3]
  TEST_ASSERT_EQUAL(23, runs[3].x);
  TEST_ASSERT_EQUAL(217, runs[3].length);
  TEST_ASSERT_EQUAL_HEX16(0x18CA, runs[3].color);  // palette[4]
}

// Rows are decoded one strip at a time straight from the download buffer, so every row
// offset and run must be checked once at load: a bad one would read past the buffer or
// draw a row wider than the screen.
void test_signed_basemap_with_a_bad_row_is_refused_and_not_drawn() {
  const std::vector<uint8_t> message = bytes(fixtures::kBasemap, sizeof(fixtures::kBasemap));
  constexpr size_t kOffsets = 6 + 4 + 32;
  constexpr size_t kRows = kOffsets + 2 * 240 + 2;
  struct Edit {
    size_t offset;
    uint8_t value;
  };
  // Row 0 is one 240-pixel run: count 1, then index 0 with length nibble 0, then length 240.
  for (const Edit& edit : {Edit{kOffsets + 2 * 239 + 1, 0xFF},  // last row's offset past the rows
                           Edit{kRows + 2, 239},                // first row covers 239 pixels
                           Edit{kRows + 2, 0},                  // a zero-length long run
                           Edit{kRows + 1, 0xF0},               // a 15-pixel short run instead
                           Edit{kRows, 0x80}}) {                // runs read on into later rows
    std::vector<uint8_t> edited = message;
    edited[edit.offset] = edit.value;
    resign(edited, g_key);
    Basemap map;
    TEST_ASSERT_EQUAL_STRING("malformed",
                             wire_result_name(map.load(edited.data(), edited.size(), g_key, fixtures::kNonce)));
    TEST_ASSERT_FALSE(map.valid());
    int calls = 0;
    map.for_each_run(0, [&](int16_t, int16_t, uint16_t) { ++calls; });
    TEST_ASSERT_EQUAL(0, calls);
  }
}

int main() {
  UNITY_BEGIN();
  RUN_TEST(test_snapshot_from_the_gateway_decodes_field_for_field);
  RUN_TEST(test_altered_or_replayed_snapshots_never_change_the_picture);
  RUN_TEST(test_signed_snapshot_with_counts_that_disagree_with_its_length_is_malformed);
  RUN_TEST(test_basemap_from_the_gateway_draws_its_runs);
  RUN_TEST(test_signed_basemap_with_a_bad_row_is_refused_and_not_drawn);
  return UNITY_END();
}
